using System.Net;
using System.Text;
using System.Text.Json;
using Nayamnyam.Core;

internal static class ViewerHost
{
    public static async Task Run(string storePath, int port)
    {
        var snapshot = new FileSnapshotStore(storePath).Load();
        var queries = new ArchitectureQueries(snapshot);
        using var listener = new HttpListener(); listener.Prefixes.Add($"http://127.0.0.1:{port}/"); listener.Start();
        Console.WriteLine($"Viewer: http://127.0.0.1:{port}/");
        while (true)
        {
            var context = await listener.GetContextAsync(); var path = context.Request.Url!.AbsolutePath; object? body = null;
            if (path == "/") { await Write(context, 200, "text/html", Html.Replace("M${a.x} ${a.y}H${b.x}", "M${a.x} ${a.y}H${b.x}V${b.y}", StringComparison.Ordinal)); continue; }
            if (path == "/api/functions") body = new { snapshotId = snapshot.Id.ToString(), functions = queries.GetFunctions().Select(function => new { id = function.Id.ToString(), displayName = function.DisplayName }) };
            else if (path == "/api/function-focus") { try { var focus = queries.GetFunctionFocus(StableId.Parse(context.Request.QueryString["id"]!)); if (focus is null) { await Write(context, 404, "text/plain", "Not found"); continue; } body = new { snapshotId = focus.SnapshotId.ToString(), functionName = focus.Function.DisplayName, functionId = focus.Function.Id.ToString(), output = new { id = focus.OutputType.Id.ToString(), name = focus.OutputType.DisplayName }, inputs = focus.Inputs.Select(input => new { id = input.Parameter.Id.ToString(), name = input.Parameter.DisplayName, type = input.Type.DisplayName }), callers = focus.DirectCallers.Select(call => new { id = call.CallId.ToString(), name = call.Function.DisplayName, functionId = call.Function.Id.ToString() }), callees = focus.DirectCallees.Select(call => new { id = call.CallId.ToString(), name = call.Function.DisplayName, functionId = call.Function.Id.ToString() }), effects = focus.DeclaredEffects.Select(effect => new { id = effect.Id.ToString(), name = effect.DisplayName }), obligations = focus.OpenMissingArguments.Select(item => new { id = item.ObligationId.ToString(), callId = item.CallId.ToString(), parameter = item.MissingParameter.DisplayName }) }; } catch (FormatException) { await Write(context, 400, "text/plain", "Invalid function ID"); continue; } }
            else { await Write(context, 404, "text/plain", "Not found"); continue; }
            await Write(context, 200, "application/json", JsonSerializer.Serialize(body));
        }
    }

    private static async Task Write(HttpListenerContext context, int status, string contentType, string content) { context.Response.StatusCode = status; context.Response.ContentType = $"{contentType}; charset=utf-8"; var bytes = Encoding.UTF8.GetBytes(content); context.Response.ContentLength64 = bytes.Length; await context.Response.OutputStream.WriteAsync(bytes); context.Response.Close(); }

    private const string Html = """
<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nayamnyam / graph review</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0b1020;color:#e5e7eb;font:14px ui-sans-serif,system-ui}header{height:58px;padding:0 22px;display:flex;align-items:center;gap:18px;border-bottom:1px solid #28334a;background:#111a2d}header b{letter-spacing:.12em;color:#8be9fd;text-transform:uppercase;font-size:12px}header span{color:#aab7cf}select,input{background:#18233a;color:#fff;border:1px solid #394968;border-radius:7px;padding:8px}#shell{display:grid;grid-template-columns:230px minmax(500px,1fr) 280px;min-height:calc(100vh - 58px)}aside{padding:18px;border-right:1px solid #28334a;background:#0e1627}aside h2,.detail h2{font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:#8da2c7}#list button{display:block;width:100%;text-align:left;border:0;background:transparent;color:#dbe7fa;padding:10px 8px;border-radius:6px;cursor:pointer}#list button:hover,#list button.active{background:#213152;color:#8be9fd}main{padding:20px;overflow:auto}.meta{display:flex;justify-content:space-between;color:#9aabc7;font-size:12px;margin-bottom:14px}svg{min-width:850px;width:100%;height:600px;background:radial-gradient(circle at 50% 40%,#182847,#101729 65%);border:1px solid #324361;border-radius:12px}.node{stroke:#d5e7ff;stroke-width:1.4;cursor:pointer}.fn{fill:#276b91}.param{fill:#334f7c}.type{fill:#5b4b91}.call{fill:#9a6434}.effect{fill:#5c7b48}.ob{fill:#993e62}.edge{stroke:#9fb7d9;stroke-width:1.3;fill:none}.label{fill:#fff;font-size:13px}.rel{fill:#b8c9e6;font-size:11px}.detail{padding:18px;border-left:1px solid #28334a;background:#0e1627;word-break:break-word}.id{color:#8be9fd;font-family:ui-monospace,monospace;font-size:12px}.pill{display:inline-block;padding:4px 7px;border-radius:99px;background:#402342;color:#ff9fbc;font-size:11px}@media(max-width:850px){#shell{grid-template-columns:1fr}.detail,aside{border:0;border-bottom:1px solid #28334a}svg{min-width:760px}}</style><header><b>Nayamnyam</b><span>Semantic graph reviewer</span><select id="f"></select><span id="state"></span></header><div id="shell"><aside><h2>Functions</h2><input id="search" placeholder="Filter functions"><div id="list"></div></aside><main><div class="meta"><span id="snap"></span><span>Focused semantic slice</span></div><svg id="g" viewBox="0 0 1000 600"></svg></main><section class="detail"><h2>Inspector</h2><div id="detail">Select a node to inspect its stable identity.</div><hr><span class="pill">Read-only</span><p>Control flow, Result paths, backend readiness, and execution are not modeled in this viewer.</p></section></div><script>const $=s=>document.querySelector(s),f=$('#f'),l=$('#list'),g=$('#g'),ns='http://www.w3.org/2000/svg';let all=[];const e=(n,a,t)=>{let x=document.createElementNS(ns,n);for(let k in a)x.setAttribute(k,a[k]);x.textContent=t||'';return x};function inspect(x){$('#detail').innerHTML=`<b>${x.name}</b><p class="id">${x.id}</p><p>${x.kind}</p>`}function node(x,y,v,k){let r=e('rect',{x,y,width:190,height:56,rx:10,class:'node '+k});r.onclick=()=>inspect({name:v.name,id:v.id||'derived',kind:k});g.append(r,e('text',{x:x+12,y:y+32,class:'label'},v.name));return{x:x+190,y:y+28}}function edge(a,b,label){g.append(e('path',{d:`M${a.x} ${a.y}H${b.x}`,class:'edge'}),e('text',{x:(a.x+b.x)/2-20,y:a.y-7,class:'rel'},label))}async function show(id){let x=await fetch('/api/function-focus?id='+encodeURIComponent(id)).then(r=>r.json());g.replaceChildren();$('#snap').textContent=x.snapshotId;$('#state').textContent=x.functionId;let core=node(405,260,{name:x.functionName,id:x.functionId},'fn');x.inputs.forEach((v,i)=>edge(node(40,80+i*85,{name:`${v.name}: ${v.type}`,id:v.id},'param'),{x:405,y:288},'input'));x.callers.forEach((v,i)=>edge(node(40,390+i*70,v,'fn'),{x:405,y:288},'calls'));x.callees.forEach((v,i)=>edge({x:595,y:288},node(780,80+i*80,v,'fn'),'calls'));x.effects.forEach((v,i)=>edge({x:595,y:300},node(780,360+i*70,v,'effect'),'effect'));x.obligations.forEach((v,i)=>node(405,430+i*70,{name:`Missing: ${v.parameter}`,id:v.id},'ob'));history.replaceState(null,'','?function='+encodeURIComponent(id));inspect({name:x.functionName,id:x.functionId,kind:'function'})}function renderList(){l.innerHTML='';all.filter(x=>x.displayName.toLowerCase().includes($('#search').value.toLowerCase())).forEach(x=>{let b=document.createElement('button');b.textContent=x.displayName;b.onclick=()=>{f.value=x.id;show(x.id)};l.append(b)})}fetch('/api/functions').then(r=>r.json()).then(x=>{all=x.functions;all.forEach(x=>f.add(new Option(x.displayName,x.id)));f.onchange=()=>show(f.value);$('#search').oninput=renderList;renderList();let id=new URLSearchParams(location.search).get('function')||f.value;f.value=id;show(id)})</script>
""";
}
